# Backend cart service logic
w("backend/src/cartService.js", """import { withTx } from "./db.js";

export async function ensureDemoCart(client) {
  // Single demo cart: id=1
  const { rows } = await client.query("SELECT id FROM carts WHERE id=1");
  if (rows.length === 0) {
    await client.query("INSERT INTO carts (id) VALUES (1)");
  }
  return 1;
}

export async function listProducts(client) {
  const { rows } = await client.query(
    `SELECT id, sku, name, price_cents, stock
     FROM products
     ORDER BY id`
  );
  return rows;
}

export async function getCart(client) {
  const cartId = await ensureDemoCart(client);

  const items = (await client.query(
    `SELECT ci.product_id,
            p.sku,
            p.name,
            ci.qty,
            ci.saved_for_later,
            ci.unit_price_cents
     FROM cart_items ci
     JOIN products p ON p.id = ci.product_id
     WHERE ci.cart_id = $1
     ORDER BY ci.product_id`,
    [cartId]
  )).rows;

  const active = items.filter(i => !i.saved_for_later);
  const saved = items.filter(i => i.saved_for_later);

  const subtotal_cents = active.reduce((sum, i) => sum + (i.unit_price_cents * i.qty), 0);
  const item_count = active.reduce((sum, i) => sum + i.qty, 0);

  return {
    cartId,
    items: active,
    savedForLater: saved,
    totals: {
      item_count,
      subtotal_cents,
    },
  };
}

export async function addToCart(productId, qty) {
  return withTx(async (client) => {
    const cartId = await ensureDemoCart(client);

    // Lock product row to safely check stock
    const productRes = await client.query(
      "SELECT id, stock, price_cents FROM products WHERE id=$1 FOR UPDATE",
      [productId]
    );
    if (productRes.rows.length === 0) {
      const err = new Error("Product not found");
      err.status = 404;
      throw err;
    }
    const product = productRes.rows[0];

    // Get existing cart item (lock row if exists)
    const itemRes = await client.query(
      "SELECT qty, saved_for_later FROM cart_items WHERE cart_id=$1 AND product_id=$2 FOR UPDATE",
      [cartId, productId]
    );

    const existingQty = itemRes.rows.length ? itemRes.rows[0].qty : 0;
    const desiredQty = existingQty + qty;

    if (desiredQty > product.stock) {
      const err = new Error(`Not enough stock. Available: ${product.stock}`);
      err.status = 409;
      throw err;
    }

    if (itemRes.rows.length === 0) {
      await client.query(
        `INSERT INTO cart_items (cart_id, product_id, qty, saved_for_later, unit_price_cents)
         VALUES ($1, $2, $3, false, $4)`,
        [cartId, productId, qty, product.price_cents]
      );
    } else {
      // If it was saved for later, keep it saved unless user toggles later
      await client.query(
        `UPDATE cart_items
         SET qty=$3
         WHERE cart_id=$1 AND product_id=$2`,
        [cartId, productId, desiredQty]
      );
    }

    return await getCart(client);
  });
}

export async function updateQuantity(productId, qty) {
  return withTx(async (client) => {
    const cartId = await ensureDemoCart(client);

    // Lock product row for stock check
    const productRes = await client.query(
      "SELECT id, stock FROM products WHERE id=$1 FOR UPDATE",
      [productId]
    );
    if (productRes.rows.length === 0) {
      const err = new Error("Product not found");
      err.status = 404;
      throw err;
    }
    const product = productRes.rows[0];

    // Lock item row
    const itemRes = await client.query(
      "SELECT qty FROM cart_items WHERE cart_id=$1 AND product_id=$2 FOR UPDATE",
      [cartId, productId]
    );
    if (itemRes.rows.length === 0) {
      const err = new Error("Item not in cart");
      err.status = 404;
      throw err;
    }

    if (qty === 0) {
      await client.query("DELETE FROM cart_items WHERE cart_id=$1 AND product_id=$2", [cartId, productId]);
      return await getCart(client);
    }

    if (qty > product.stock) {
      const err = new Error(`Not enough stock. Available: ${product.stock}`);
      err.status = 409;
      throw err;
    }

    await client.query(
      "UPDATE cart_items SET qty=$3 WHERE cart_id=$1 AND product_id=$2",
      [cartId, productId, qty]
    );

    return await getCart(client);
  });
}

export async function toggleSaveForLater(productId, saved) {
  return withTx(async (client) => {
    const cartId = await ensureDemoCart(client);

    const itemRes = await client.query(
      "SELECT product_id FROM cart_items WHERE cart_id=$1 AND product_id=$2 FOR UPDATE",
      [cartId, productId]
    );
    if (itemRes.rows.length === 0) {
      const err = new Error("Item not in cart");
      err.status = 404;
      throw err;
    }

    await client.query(
      "UPDATE cart_items SET saved_for_later=$3 WHERE cart_id=$1 AND product_id=$2",
      [cartId, productId, saved]
    );

    return await getCart(client);
  });
}

export async function removeItem(productId) {
  return withTx(async (client) => {
    const cartId = await ensureDemoCart(client);
    await client.query("DELETE FROM cart_items WHERE cart_id=$1 AND product_id=$2", [cartId, productId]);
    return await getCart(client);
  });
}
""")

# Backend routes and server
w("backend/src/server.js", """import express from "express";
import cors from "cors";
import dotenv from "dotenv";
dotenv.config();

import { pool } from "./db.js";
import { addItemSchema, updateQtySchema, saveSchema, parseJson } from "./validate.js";
import { listProducts, getCart, addToCart, updateQuantity, toggleSaveForLater, removeItem } from "./cartService.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/health", (req, res) => res.json({ ok: true }));

app.get("/api/products", async (req, res, next) => {
  try {
    const client = await pool.connect();
    try {
      const products = await listProducts(client);
      res.json({ products });
    } finally {
      client.release();
    }
  } catch (e) { next(e); }
});

app.get("/api/cart", async (req, res, next) => {
  try {
    const client = await pool.connect();
    try {
      const cart = await getCart(client);
      res.json(cart);
    } finally {
      client.release();
    }
  } catch (e) { next(e); }
});

app.post("/api/cart/items", async (req, res, next) => {
  try {
    const body = parseJson(req);
    const parsed = addItemSchema.safeParse(body);
    if (!parsed.success) {
      return res.status(400).json({ error: "Invalid input", details: parsed.error.flatten() });
    }
    const cart = await addToCart(parsed.data.productId, parsed.data.qty);
    res.json(cart);
  } catch (e) { next(e); }
});

app.patch("/api/cart/items/:productId", async (req, res, next) => {
  try {
    const productId = Number(req.params.productId);
    const body = parseJson(req);

    if (!Number.isInteger(productId) || productId <= 0) {
      return res.status(400).json({ error: "Invalid input", details: { productId: "Must be a positive integer" } });
    }

    const parsed = updateQtySchema.safeParse(body);
    if (!parsed.success) {
      return res.status(400).json({ error: "Invalid input", details: parsed.error.flatten() });
    }

    const cart = await updateQuantity(productId, parsed.data.qty);
    res.json(cart);
  } catch (e) { next(e); }
});

app.post("/api/cart/items/:productId/save", async (req, res, next) => {
  try {
    const productId = Number(req.params.productId);
    const body = parseJson(req);

    if (!Number.isInteger(productId) || productId <= 0) {
      return res.status(400).json({ error: "Invalid input", details: { productId: "Must be a positive integer" } });
    }

    const parsed = saveSchema.safeParse(body);
    if (!parsed.success) {
      return res.status(400).json({ error: "Invalid input", details: parsed.error.flatten() });
    }

    const cart = await toggleSaveForLater(productId, parsed.data.saved);
    res.json(cart);
  } catch (e) { next(e); }
});

app.delete("/api/cart/items/:productId", async (req, res, next) => {
  try {
    const productId = Number(req.params.productId);
    if (!Number.isInteger(productId) || productId <= 0) {
      return res.status(400).json({ error: "Invalid input", details: { productId: "Must be a positive integer" } });
    }
    const cart = await removeItem(productId);
    res.json(cart);
  } catch (e) { next(e); }
});

// Error handler (always return friendly JSON)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const debug = String(process.env.DEBUG_ERRORS || "false").toLowerCase() === "true";
  const payload = { error: err.message || "Server error" };
  if (debug && err.stack) payload.stack = err.stack;
  res.status(status).json(payload);
});

const port = Number(process.env.PORT || 4000);
app.listen(port, () => {
  console.log(`Backend listening on http://localhost:${port}`);
});
""")

