w("frontend/src/api.js", """const API_URL = import.meta.env.VITE_API_URL || "http://localhost:4000";

async function request(path, options = {}) {
  const res = await fetch(`${API_URL}${path}`, {
    headers: { "Content-Type": "application/json", ...(options.headers || {}) },
    ...options,
  });

  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const msg = data?.error || "Request failed";
    const err = new Error(msg);
    err.status = res.status;
    err.details = data?.details;
    throw err;
  }
  return data;
}

export const api = {
  getProducts: () => request("/api/products"),
  getCart: () => request("/api/cart"),
  addItem: (productId, qty = 1) =>
    request("/api/cart/items", { method: "POST", body: JSON.stringify({ productId, qty }) }),
  updateQty: (productId, qty) =>
    request(`/api/cart/items/${productId}`, { method: "PATCH", body: JSON.stringify({ qty }) }),
  saveForLater: (productId, saved) =>
    request(`/api/cart/items/${productId}/save`, { method: "POST", body: JSON.stringify({ saved }) }),
  removeItem: (productId) =>
    request(`/api/cart/items/${productId}`, { method: "DELETE" }),
};
""")

w("frontend/src/money.js", """export function formatCents(cents) {
  const n = Number(cents || 0);
  const sign = n < 0 ? "-" : "";
  const abs = Math.abs(n);
  const dollars = Math.floor(abs / 100);
  const remainder = abs % 100;
  return `${sign}${dollars}.${String(remainder).padStart(2, "0")}`;
}
""")

w("frontend/src/App.jsx", """import React, { useEffect, useMemo, useState } from "react";
import { api } from "./api";
import { formatCents } from "./money";

function Button({ children, onClick, disabled, variant = "primary" }) {
  return (
    <button className={`btn ${variant}`} onClick={onClick} disabled={disabled}>
      {children}
    </button>
  );
}

function QtyControl({ qty, onDec, onInc, disabledDec, disabledInc }) {
  return (
    <div className="qty">
      <Button variant="secondary" onClick={onDec} disabled={disabledDec}>−</Button>
      <span className="qtyValue">{qty}</span>
      <Button variant="secondary" onClick={onInc} disabled={disabledInc}>+</Button>
    </div>
  );
}

export default function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const productById = useMemo(() => {
    const m = new Map();
    for (const p of products) m.set(p.id, p);
    return m;
  }, [products]);

  async function refreshAll() {
    setError("");
    const [p, c] = await Promise.all([api.getProducts(), api.getCart()]);
    setProducts(p.products);
    setCart(c);
  }

  useEffect(() => {
    refreshAll().catch(e => setError(e.message));
  }, []);

  async function doAction(fn) {
    setBusy(true);
    setError("");
    try {
      const updated = await fn();
      // Some endpoints already return the cart
      if (updated?.cartId) setCart(updated);
      else await refreshAll();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  }

  if (!cart) {
    return (
      <div className="container">
        <h1>Shopping Cart</h1>
        <p>Loading…</p>
        {error ? <div className="error">{error}</div> : null}
      </div>
    );
  }

  const subtotal = cart?.totals?.subtotal_cents ?? 0;

  return (
    <div className="container">
      <header className="header">
        <h1>Shopping Cart</h1>
        <div className="pill">Active items: {cart.totals.item_count}</div>
      </header>

      {error ? <div className="error">{error}</div> : null}

      <section className="grid">
        <div className="card">
          <h2>Products</h2>
          <p className="muted">Click “Add to cart”. Stock is checked on the server.</p>

          <div className="list">
            {products.map((p) => (
              <div key={p.id} className="row">
                <div className="rowMain">
